extends CharacterBody2D

const GRAVITY: float = 980.0

func _physics_process(delta: float) -> void:
	if is_on_floor():
		velocity.y = 0.0
	else:
		velocity.y += GRAVITY * delta
	move_and_slide()

extends RefCounted


static func save_data(data: Dictionary, path: String) -> void:
	var file := FileAccess.open(path, FileAccess.WRITE)
	if file == null:
		push_error("Failed to open file for saving: %s" % path)
		return
	file.store_string(JSON.stringify(data))
	file.close()


static func load_data(path: String) -> Dictionary:
	var file := FileAccess.open(path, FileAccess.READ)
	if file == null:
		push_error("Failed to open file for loading: %s" % path)
		return {}
	var contents := file.get_as_text()
	file.close()
	var json := JSON.new()
	if json.parse(contents) != OK:
		push_error("Failed to parse JSON in file: %s" % path)
		return {}
	if not (json.data is Dictionary):
		push_error("JSON in file is not a Dictionary: %s" % path)
		return {}
	return json.data

extends RefCounted

var _items: Dictionary = {}


func add_item(item_name: String, count: int) -> void:
	if count > 0:
		_items[item_name] = get_count(item_name) + count


func remove_item(item_name: String, count: int) -> bool:
	if count < 0 or get_count(item_name) < count:
		return false
	if count > 0:
		_items[item_name] = get_count(item_name) - count
	return true


func get_count(item_name: String) -> int:
	return int(_items.get(item_name, 0))

