func first_hit(from: Vector2, to: Vector2) -> Vector2:
	var query := PhysicsRayQueryParameters2D.create(from, to)
	var hit := get_world_2d().direct_space_state.intersect_ray(query)
	if hit.is_empty():
		return to
	return hit["position"]

extends RefCounted


func find_path(size: Vector2i, walls: Array[Vector2i], from: Vector2i, to: Vector2i) -> Array[Vector2i]:
	var path: Array[Vector2i] = []
	if size.x <= 0 or size.y <= 0:
		return path
	if not _in_bounds(from, size) or not _in_bounds(to, size):
		return path

	var blocked: Dictionary = {}
	for wall in walls:
		blocked[wall] = true
	if blocked.has(from) or blocked.has(to):
		return path

	var queue: Array[Vector2i] = [from]
	var parents: Dictionary = {from: from}
	var head: int = 0
	var directions: Array[Vector2i] = [Vector2i.UP, Vector2i.DOWN, Vector2i.LEFT, Vector2i.RIGHT]
	while head < queue.size():
		var cell: Vector2i = queue[head]
		head += 1
		if cell == to:
			var cursor: Vector2i = to
			while cursor != from:
				path.append(cursor)
				cursor = parents[cursor]
			path.append(from)
			path.reverse()
			return path
		for direction in directions:
			var neighbor: Vector2i = cell + direction
			if not _in_bounds(neighbor, size) or blocked.has(neighbor) or parents.has(neighbor):
				continue
			parents[neighbor] = cell
			queue.append(neighbor)
	return path


func _in_bounds(cell: Vector2i, size: Vector2i) -> bool:
	return cell.x >= 0 and cell.y >= 0 and cell.x < size.x and cell.y < size.y

