class WaitRace:
	extends RefCounted
	signal finished(signal_won: bool)
	var settled := false

	func settle(signal_won: bool) -> void:
		if settled:
			return
		settled = true
		finished.emit(signal_won)


func wait_for(sig: Signal, seconds: float) -> bool:
	var race := WaitRace.new()
	var on_signal := func() -> void: race.settle(true)
	var on_timeout := func() -> void: race.settle(false)
	var timer := get_tree().create_timer(maxf(seconds, 0.0), false)
	sig.connect(on_signal, CONNECT_ONE_SHOT)
	timer.timeout.connect(on_timeout, CONNECT_ONE_SHOT)
	var signal_won: bool = await race.finished
	if sig.is_connected(on_signal):
		sig.disconnect(on_signal)
	if timer.timeout.is_connected(on_timeout):
		timer.timeout.disconnect(on_timeout)
	return signal_won
